//
//  Ray Marching / Volumetric Effects
//  Native Metal Shader - 3D Effects
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float effect_intensity;
    float ray_steps;
    float depth;
    float rotation_speed;
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// MARK: - SDF Functions

float sdSphere(float3 p, float r) {
    return length(p) - r;
}

float sdBox(float3 p, float3 b) {
    float3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float sdTorus(float3 p, float2 t) {
    float2 q = float2(length(p.xz) - t.x, p.y);
    return length(q) - t.y;
}

// Smooth minimum for blending shapes
float smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

// Scene SDF
float sceneSDF(float3 p, float time) {
    // Rotating torus
    float angle = time * 0.5;
    float3 rotated = float3(
        p.x * cos(angle) - p.z * sin(angle),
        p.y,
        p.x * sin(angle) + p.z * cos(angle)
    );

    float torus = sdTorus(rotated, float2(0.5, 0.2));

    // Pulsing sphere
    float sphere = sdSphere(p, 0.3 + sin(time * 2.0) * 0.1);

    // Combine shapes
    return smin(torus, sphere, 0.3);
}

// Calculate normal using gradient
float3 calcNormal(float3 p, float time) {
    const float eps = 0.001;
    float2 h = float2(eps, 0.0);
    return normalize(float3(
        sceneSDF(p + h.xyy, time) - sceneSDF(p - h.xyy, time),
        sceneSDF(p + h.yxy, time) - sceneSDF(p - h.yxy, time),
        sceneSDF(p + h.yyx, time) - sceneSDF(p - h.yyx, time)
    ));
}

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    // Sample original image
    float4 color = sourceTexture.sample(textureSampler, in.texCoord);

    float time = float(uniforms.FrameCount) * uniforms.rotation_speed * 0.01;

    // Ray setup
    float2 uv = (in.texCoord * 2.0 - 1.0);
    uv.x *= uniforms.OutputSize.x / uniforms.OutputSize.y;

    float3 ro = float3(0.0, 0.0, -2.0); // Ray origin
    float3 rd = normalize(float3(uv, 1.0)); // Ray direction

    // Ray marching
    float t = 0.0;
    int steps = int(uniforms.ray_steps);
    bool hit = false;

    for (int i = 0; i < steps; i++) {
        float3 p = ro + rd * t;
        float d = sceneSDF(p, time);

        if (d < 0.001) {
            hit = true;
            break;
        }

        t += d;

        if (t > uniforms.depth) break;
    }

    // Shading
    if (hit) {
        float3 p = ro + rd * t;
        float3 normal = calcNormal(p, time);

        // Lighting
        float3 lightDir = normalize(float3(1.0, 1.0, -1.0));
        float diff = max(dot(normal, lightDir), 0.0);
        float spec = pow(max(dot(reflect(-lightDir, normal), -rd), 0.0), 32.0);

        // Color based on position
        float3 objColor = float3(
            0.5 + 0.5 * sin(p.x * 3.0 + time),
            0.5 + 0.5 * sin(p.y * 3.0 + time * 1.3),
            0.5 + 0.5 * sin(p.z * 3.0 + time * 1.7)
        );

        float3 shaded = objColor * (0.3 + 0.7 * diff) + float3(spec);

        // Mix with original image
        color.rgb = mix(color.rgb, shaded, uniforms.effect_intensity);
    }

    return color;
}

